import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { configApi, departmentsApi, subjectsApi, facultyApi, timetablesApi } from '../services/api';
import './Dashboard.css';

const CARDS = [
  { to: '/config', icon: '⚙', label: 'Academic Config', color: 'config', getCount: (d) => `${d.config?.workingDays?.length || 0} days × ${d.config?.periodsPerDay || 0} periods` },
  { to: '/departments', icon: '🏛', label: 'Departments', color: 'dept', getCount: (d) => `${d.departments?.length || 0} department(s)` },
  { to: '/subjects', icon: '📚', label: 'Subjects', color: 'subject', getCount: (d) => `${d.subjects?.length || 0} subject(s)` },
  { to: '/faculty', icon: '👤', label: 'Faculty', color: 'faculty', getCount: (d) => `${d.faculty?.length || 0} faculty member(s)` },
  { to: '/timetables', icon: '📅', label: 'Timetables', color: 'timetable', getCount: (d) => `${d.timetables?.length || 0} generated` }
];

const STEPS = [
  { num: 1, text: 'Set Academic Configuration', to: '/config', desc: 'Working days & periods per day' },
  { num: 2, text: 'Add Departments', to: '/departments', desc: 'With section counts' },
  { num: 3, text: 'Add Faculty', to: '/faculty', desc: 'With workload limits' },
  { num: 4, text: 'Add Subjects', to: '/subjects', desc: 'Per semester/department, assign faculty & rooms' },
  { num: 5, text: 'Generate Timetables', to: '/timetables', desc: 'Select semester and generate' }
];

function Dashboard() {
  const [config, setConfig] = useState(null);
  const [departments, setDepartments] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [faculty, setFaculty] = useState([]);
  const [timetables, setTimetables] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    Promise.all([
      configApi.get().catch(() => null),
      departmentsApi.getAll().catch(() => []),
      subjectsApi.getAll().catch(() => []),
      facultyApi.getAll().catch(() => []),
      timetablesApi.getAll().catch(() => [])
    ]).then(([c, d, s, f, t]) => {
      setConfig(c);
      setDepartments(d);
      setSubjects(s);
      setFaculty(f);
      setTimetables(t);
      setLoading(false);
    }).catch(() => {
      setError('Failed to load data');
      setLoading(false);
    });
  }, []);

  if (loading) return <div className="page-loading">Loading...</div>;
  if (error) return <div className="alert alert-error">{error}</div>;

  const data = { config, departments, subjects, faculty, timetables };
  const totalSlots = (config?.workingDays?.length || 0) * (config?.periodsPerDay || 0) * (timetables?.length || 0);

  return (
    <div className="dashboard">
      <div className="dashboard-hero">
        <div className="dashboard-hero-bg" aria-hidden="true" />
        <div className="dashboard-hero-content">
          <h1 className="dashboard-title">College Timetable Generator</h1>
          <p className="dashboard-tagline">Create and manage academic schedules for your institution</p>
          <div className="dashboard-stats">
            <div className="dashboard-stat">
              <span className="dashboard-stat-value">{departments.length}</span>
              <span className="dashboard-stat-label">Departments</span>
            </div>
            <div className="dashboard-stat">
              <span className="dashboard-stat-value">{subjects.length}</span>
              <span className="dashboard-stat-label">Subjects</span>
            </div>
            <div className="dashboard-stat">
              <span className="dashboard-stat-value">{faculty.length}</span>
              <span className="dashboard-stat-label">Faculty</span>
            </div>
            <div className="dashboard-stat">
              <span className="dashboard-stat-value">{timetables.length}</span>
              <span className="dashboard-stat-label">Timetables</span>
            </div>
          </div>
        </div>
      </div>

      <section className="dashboard-section">
        <h2 className="dashboard-section-title">Quick Access</h2>
        <div className="dashboard-cards">
          {CARDS.map((card) => (
            <Link key={card.to} to={card.to} className={`dashboard-card dashboard-card--${card.color}`}>
              <span className="dashboard-card-icon">{card.icon}</span>
              <div className="dashboard-card-body">
                <h3>{card.label}</h3>
                <p>{card.getCount(data)}</p>
              </div>
              <span className="dashboard-card-arrow">→</span>
            </Link>
          ))}
        </div>
      </section>

      <section className="dashboard-section dashboard-quick-section">
        <h2 className="dashboard-section-title">Quick Start Guide</h2>
        <div className="dashboard-steps">
          {STEPS.map((step) => (
            <Link key={step.num} to={step.to} className="dashboard-step">
              <span className="dashboard-step-num">{step.num}</span>
              <div className="dashboard-step-content">
                <h3>{step.text}</h3>
                <p>{step.desc}</p>
              </div>
              <span className="dashboard-step-arrow">→</span>
            </Link>
          ))}
        </div>
      </section>
    </div>
  );
}

export default Dashboard;
